CREATE OR REPLACE VIEW VW_A_IMPORTI_NON_RIDOTTI as SELECT registrazioni.id as id, registrazioni.importo as importo_registrazione, NVL(SUM(reg_io_assegnazioni.importo), 0) as incassato, registrazioni.importo - SUM(NVL(reg_io_assegnazioni.importo, 0)) as saldo, registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 0 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id, registrazioni.importo, registrazioni.software, registrazioni.idcomune;
CREATE OR REPLACE VIEW VW_A_IMPORTI_RIDOTTI as SELECT registrazioni.id as id, registrazioni.importo as importo_registrazione, NVL(SUM(reg_io_assegnazioni.importo), 0) as incassato, SUM(registrazioni_importi.importo) - SUM(NVL(reg_io_assegnazioni.importo, 0)) as saldo, registrazioni.idcomune as idcomune FROM registrazioni LEFT OUTER JOIN registrazioni_importi LEFT OUTER JOIN reg_io_assegnazioni ON registrazioni_importi.idcomune = reg_io_assegnazioni.idcomune AND registrazioni_importi.id = reg_io_assegnazioni.fk_riid ON registrazioni.idcomune=registrazioni_importi.idcomune  AND registrazioni.id=registrazioni_importi.fk_rgid WHERE (registrazioni_importi.flag_nonprevincassi = 1 or registrazioni_importi.flag_nonprevincassi  is NULL)  GROUP BY registrazioni.id, registrazioni.importo, registrazioni.software, registrazioni.idcomune;
CREATE OR REPLACE VIEW VW_ALBEROPROC
  AS
  SELECT ALBEROPROC.IDCOMUNE,
    ALBEROPROC.SOFTWARE,
    ALBEROPROC.SC_ID,
    ALBEROPROC.SC_CODICE,
    ALBEROPROC.SC_PADRE,
    DECODE(NVL(ALBEROPROC_L4.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L4.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L3.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L3.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L2.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L2.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L1.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L1.SC_DESCRIZIONE , ' - ' ))
    || ALBEROPROC.SC_DESCRIZIONE AS SC_DESCRIZIONE,
    DECODE(NVL(ALBEROPROC_L4.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L4.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L3.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L3.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L2.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L2.SC_DESCRIZIONE , ' - ' ))
    || DECODE(NVL(ALBEROPROC_L1.SC_DESCRIZIONE,'NULL'),'NULL','',CONCAT(ALBEROPROC_L1.SC_DESCRIZIONE , ' - ' )) AS SC_DESCRIZIONEPADRE,
    ALBEROPROC.SC_DESCRIZIONE                                                                                   AS SC_DESCRIZIONEBREVE,
    ALBEROPROC.SC_ORDINE                                                                                        AS ORDINE0,
    NVL(ALBEROPROC_L1.SC_ORDINE,0)                                                                              AS ORDINE1,
    NVL(ALBEROPROC_L2.SC_ORDINE,0)                                                                              AS ORDINE2,
    NVL(ALBEROPROC_L3.SC_ORDINE,0)                                                                              AS ORDINE3,
    NVL(ALBEROPROC_L4.SC_ORDINE,0)                                                                              AS ORDINE4,
    (
    CASE ALBEROPROC.FKCODICEMERCATO
      WHEN NULL
      THEN (
        CASE ALBEROPROC_L1.FKCODICEMERCATO
          WHEN NULL
          THEN (
            CASE ALBEROPROC_L2.FKCODICEMERCATO
              WHEN NULL
              THEN (
                CASE ALBEROPROC_L3.FKCODICEMERCATO
                  WHEN NULL
                  THEN ALBEROPROC_L4.FKCODICEMERCATO
                  ELSE ALBEROPROC_L3.FKCODICEMERCATO
                END )
              ELSE ALBEROPROC_L2.FKCODICEMERCATO
            END )
          ELSE ALBEROPROC_L1.FKCODICEMERCATO
        END )
      ELSE ALBEROPROC.FKCODICEMERCATO
    END ) AS FKCODICEMERCATO,
    (
    CASE ALBEROPROC.FKIDMERCATIUSO
      WHEN NULL
      THEN (
        CASE ALBEROPROC_L1.FKIDMERCATIUSO
          WHEN NULL
          THEN (
            CASE ALBEROPROC_L2.FKIDMERCATIUSO
              WHEN NULL
              THEN (
                CASE ALBEROPROC_L3.FKIDMERCATIUSO
                  WHEN NULL
                  THEN ALBEROPROC_L4.FKIDMERCATIUSO
                  ELSE ALBEROPROC_L3.FKIDMERCATIUSO
                END)
              ELSE ALBEROPROC_L2.FKIDMERCATIUSO
            END)
          ELSE ALBEROPROC_L1.FKIDMERCATIUSO
        END)
      ELSE ALBEROPROC.FKIDMERCATIUSO
    END) AS FKIDMERCATIUSO,
    ALBEROPROC.SC_ATTIVO,
    ALBEROPROC.PROGRESSIVOISTANZE
  FROM ALBEROPROC
  LEFT JOIN ALBEROPROC ALBEROPROC_L1
  ON ALBEROPROC_L1.IDCOMUNE   = ALBEROPROC.IDCOMUNE
  AND ALBEROPROC_L1.SOFTWARE  = ALBEROPROC.SOFTWARE
  AND ALBEROPROC_L1.SC_CODICE = SUBSTR(ALBEROPROC.SC_CODICE,1,(LENGTH(ALBEROPROC.SC_CODICE)-2))
  LEFT JOIN ALBEROPROC ALBEROPROC_L2
  ON ALBEROPROC_L2.IDCOMUNE   = ALBEROPROC_L1.IDCOMUNE
  AND ALBEROPROC_L2.SOFTWARE  = ALBEROPROC_L1.SOFTWARE
  AND ALBEROPROC_L2.SC_CODICE = SUBSTR(ALBEROPROC_L1.SC_CODICE,1,(LENGTH(ALBEROPROC_L1.SC_CODICE)-2))
  LEFT JOIN ALBEROPROC ALBEROPROC_L3
  ON ALBEROPROC_L3.IDCOMUNE   = ALBEROPROC_L2.IDCOMUNE
  AND ALBEROPROC_L3.SOFTWARE  = ALBEROPROC_L2.SOFTWARE
  AND ALBEROPROC_L3.SC_CODICE = SUBSTR(ALBEROPROC_L2.SC_CODICE,1,(LENGTH(ALBEROPROC_L2.SC_CODICE)-2))
  LEFT JOIN ALBEROPROC ALBEROPROC_L4
  ON ALBEROPROC_L4.IDCOMUNE   = ALBEROPROC_L3.IDCOMUNE
  AND ALBEROPROC_L4.SOFTWARE  = ALBEROPROC_L3.SOFTWARE
  AND ALBEROPROC_L4.SC_CODICE = SUBSTR(ALBEROPROC_L3.SC_CODICE,1,(LENGTH(ALBEROPROC_L3.SC_CODICE)-2));
CREATE OR REPLACE VIEW VW_ANAGRAFEINTERDETTI
AS
  SELECT idcomune,
    codiceanagrafe,
    MAX(datascadenza) AS datascadenza
  FROM scadenze
  WHERE datascadenza > SYSDATE
  AND categoria     ='I'
  GROUP BY idcomune,
    codiceanagrafe;
CREATE OR REPLACE VIEW VW_ANAGRAFE_LOCALIZZAZIONI
AS
  SELECT ANAGRAFE.IDCOMUNE,
    ANAGRAFE.CODICEANAGRAFE,
    TRIM( ANAGRAFE.NOMINATIVO || ' ' || ANAGRAFE.NOME) AS NOMINATIVO,
    ANAGRAFE.INDIRIZZO                                           AS INDIRIZZO_RESIDENZA,
    DECODE(NVL(ANAGRAFE.CAP, '0'), 0, '', ANAGRAFE.CAP || ', ') ||
    DECODE(NVL(COMUNI_RESIDENZA.COMUNE, '0'), 0, '', COMUNI_RESIDENZA.COMUNE) ||
    DECODE(NVL(ANAGRAFE.CITTA, '0'), 0, '', ', ' || ANAGRAFE.CITTA) ||
    DECODE(NVL(ANAGRAFE.PROVINCIA, '0'), 0, '', ' (' || ANAGRAFE.PROVINCIA || ')') AS LOCALIZZAZIONE_RESIDENZA,
    ANAGRAFE.INDIRIZZOCORRISPONDENZA AS INDIRIZZO_CORRISPONDENZA,
    DECODE(NVL(ANAGRAFE.CAPCORRISPONDENZA, '0'), 0, '', ANAGRAFE.CAPCORRISPONDENZA || ', ') ||
    DECODE(NVL(COMUNI_CORRISPONDENZA.COMUNE, '0'), 0, '', COMUNI_CORRISPONDENZA.COMUNE) ||
    DECODE(NVL(ANAGRAFE.CITTACORRISPONDENZA, '0'), 0, '', ', ' || ANAGRAFE.CITTACORRISPONDENZA) ||
    DECODE(NVL(ANAGRAFE.PROVINCIACORRISPONDENZA, '0'), 0, '', ' (' || ANAGRAFE.PROVINCIACORRISPONDENZA || ')') AS LOCALIZZAZIONE_CORRISPONDENZA,
    CASE NVL(ANAGRAFE.INDIRIZZOCORRISPONDENZA, '0')
      WHEN '0'
      THEN 0
      ELSE 1
    END AS IS_CORRISPONDENZA
  FROM ANAGRAFE
  LEFT OUTER JOIN COMUNI COMUNI_RESIDENZA
  ON ANAGRAFE.COMUNERESIDENZA = COMUNI_RESIDENZA.CODICECOMUNE
  LEFT OUTER JOIN COMUNI COMUNI_CORRISPONDENZA
  ON ANAGRAFE.COMUNECORRISPONDENZA = COMUNI_CORRISPONDENZA.CODICECOMUNE;
-- CONTINUARE DA QUI LA CORREZIONE DEGLI SCRIPT DI CREAZIONE DELLE VISTE
CREATE OR REPLACE VIEW VW_A_REG_IMPORTI_DEBITI as SELECT REGISTRAZIONI.ID as ID_REGISTRAZIONE, REGISTRAZIONI.SOFTWARE, REGISTRAZIONI.IDCOMUNE, REGISTRAZIONI_IMPORTI.ID, REGISTRAZIONI_IMPORTI.IMPORTO, REGISTRAZIONI_IMPORTI.NR_RATA as RATA, SUM(REG_IO_ASSEGNAZIONI.IMPORTO) as INCASSATO FROM REGISTRAZIONI_IMPORTI LEFT OUTER JOIN REG_IO_ASSEGNAZIONI ON REGISTRAZIONI_IMPORTI.IDCOMUNE=REG_IO_ASSEGNAZIONI.IDCOMUNE  AND REGISTRAZIONI_IMPORTI.ID=REG_IO_ASSEGNAZIONI.FK_RIID, REGISTRAZIONI WHERE REGISTRAZIONI.IDCOMUNE = REGISTRAZIONI_IMPORTI.IDCOMUNE AND REGISTRAZIONI.ID = REGISTRAZIONI_IMPORTI.FK_RGID AND REGISTRAZIONI_IMPORTI.FLAG_NONPREVINCASSI = 0 GROUP BY REGISTRAZIONI.ID, REGISTRAZIONI_IMPORTI.ID, REGISTRAZIONI_IMPORTI.IMPORTO, REGISTRAZIONI_IMPORTI.NR_RATA, REGISTRAZIONI.SOFTWARE, REGISTRAZIONI.IDCOMUNE HAVING NVL(SUM(REG_IO_ASSEGNAZIONI.IMPORTO),  0) < REGISTRAZIONI_IMPORTI.IMPORTO;
CREATE OR REPLACE VIEW VW_A_REGISTRAZIONI_DEBITI as SELECT id_REGISTRAZIONE, IDCOMUNE, SOFTWARE, rata as rata_non_pagata, SUM(importo) as importo_rata, NVL(SUM(incassato),  0) as incassato_rata, (SUM(IMPORTO) - NVL(SUM(incassato),  0)) as DA_INCASSARE FROM  VW_A_REG_IMPORTI_DEBITI 	 GROUP BY ID_REGISTRAZIONE, SOFTWARE, IDCOMUNE,rata;
Create Or Replace View VW_A_SALDO_RIDOTTI as SELECT registrazioni.id as id, SUM(registrazioni_importi.importo) saldo, registrazioni.idcomune as idcomune FROM  registrazioni,  registrazioni_importi WHERE registrazioni_importi.idcomune = registrazioni.idcomune and registrazioni_importi.fk_rgid = registrazioni.id and registrazioni_importi.flag_nonprevincassi = 1 GROUP BY registrazioni.id, registrazioni.idcomune;
Create Or Replace View VW_ASSENZECONCESSIONARI as SELECT COUNT(*) as numero_assenze, mercati.codicemercato, MERCATI.descrizione as MERCATO, mercati_uso.id as codiceuso, mercati_uso.descrizione as USO, mercati_d.idposteggio, MERCATI_D.codiceposteggio as POSTEGGIO, anagrafe.codiceanagrafe, ANAGRAFE.NOMINATIVO, ANAGRAFE.NOME, mercatipresenze_t.anno, mercatipresenze_t.software, mercatipresenze_t.idcomune FROM  MERCATIPRESENZE_D,  ANAGRAFE,  MERCATI,  MERCATI_USO,  MERCATI_D,  MERCATIPRESENZE_T WHERE MERCATIPRESENZE_D.IDCOMUNE = mercatipresenze_t.idcomune and MERCATIPRESENZE_D.fkidtestata = mercatipresenze_t.id and mercatipresenze_d.idcomune = anagrafe.idcomune and mercatipresenze_d.codiceconcessionario = anagrafe.codiceanagrafe and MERCATI.IDCOMUNE = mercatipresenze_T.idcomune and mercati.codicemercato = mercatipresenze_T.fkcodicemercato and MERCATI_USO.IDCOMUNE = MERCATIPRESENZE_T.IDCOMUNE and MERCATI_USO.id = MERCATIPRESENZE_T.fkidmercatiuso and mercati_d.idcomune = MERCATIPRESENZE_D.idcomune and mercati_d.idposteggio = mercatipresenze_d.fkidposteggio and codiceconcessionario  is not  NULL and ( ( MERCATIPRESENZE_D.CODICEANAGRAFE <> CODICECONCESSIONARIO) or MERCATIPRESENZE_D.CODICEANAGRAFE  is  NULL ) and ( flag_assenza_giust  is  NULL or flag_assenza_giust = 0) GROUP BY anagrafe.nominativo, anagrafe.nomE, MERCATI.descrizione, mercati_uso.descrizione, mercati_d.idposteggio, MERCATI_D.codiceposteggio, mercati.codicemercato, mercatipresenze_t.anno, mercatipresenze_t.software, mercatipresenze_t.idcomune, anagrafe.codiceanagrafe, mercati_uso.id ORDER BY mercato,uso, posteggio, nominativo,nome;
Create Or Replace View VW_CCICT_DESTINAZIONI as SELECT CC_ICALCOLOTOT.IDCOMUNE, CC_ICALCOLOTOT.ID as CCICT_ID, CC_DESTINAZIONI.ID as CCDE_ID, CC_DESTINAZIONI.DESTINAZIONE FROM  CC_DESTINAZIONI,  ISTANZE,  CC_ICALCOLOTOT WHERE ISTANZE.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and ISTANZE.CODICEISTANZA = CC_ICALCOLOTOT.CODICEISTANZA and CC_DESTINAZIONI.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and CC_DESTINAZIONI.FK_OCCBDE_ID = CC_ICALCOLOTOT.FK_OCCBDE_ID and CC_DESTINAZIONI.SOFTWARE = ISTANZE.SOFTWARE;
Create Or Replace View VW_CCICT_TIPIINTERVENTO as SELECT CC_ICALCOLOTOT.IDCOMUNE, CC_ICALCOLOTOT.ID as CCICT_ID, CC_TIPOINTERVENTO.ID as CCTI_ID, CC_TIPOINTERVENTO.INTERVENTO FROM  CC_TIPOINTERVENTO,  ISTANZE,  CC_ICALCOLOTOT WHERE ISTANZE.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and ISTANZE.CODICEISTANZA = CC_ICALCOLOTOT.CODICEISTANZA and CC_TIPOINTERVENTO.IDCOMUNE = CC_ICALCOLOTOT.IDCOMUNE and CC_TIPOINTERVENTO.FK_OCCBTI_ID = CC_ICALCOLOTOT.FK_OCCBTI_ID and CC_TIPOINTERVENTO.SOFTWARE = ISTANZE.SOFTWARE;
CREATE OR REPLACE VIEW VW_CONCESSIONIATTIVE
AS
  SELECT istanze.idcomune,
    istanze.software,
    autorizzazioni.id AS codiceconcessione,
    istanze.codiceistanza,
    autorizzazioni.fk_codiceanagrafe AS codicetitolare,
    CASE NVL(istanze.codicetitolarelegale, -1)
      WHEN                                 -1
      THEN istanze.codicerichiedente
      ELSE istanze. codicetitolarelegale
    END AS codiceoccupante,
    autorizzazioni_concessioni.fk_codicemercato,
    autorizzazioni_concessioni.fk_idmercatiuso,
    autorizzazioni_concessioni.fk_idposteggio
  FROM istanze,
    autorizzazioni,
    autorizzazioni_concessioni
  WHERE autorizzazioni.idcomune        = istanze.idcomune
  AND autorizzazioni.fkidistanza       = istanze.codiceistanza
  AND autorizzazioni.idcomune          = autorizzazioni_concessioni.idcomune
  AND AUTORIZZAZIONI.id                = AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE
  AND (autorizzazioni.flag_attiva      = 1
  AND (AUTORIZZAZIONI.DATA_CESSAZIONE >= sysdate
  OR autorizzazioni.data_cessazione   IS NULL));
Create Or Replace View VW_I_ATTIVITAAUTORIZZAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, AUTORIZZAZIONI.AUTORIZNUMERO, AUTORIZZAZIONI.AUTORIZDATA, AUTORIZZAZIONI.AUTORIZDATAREGISTR, AUTORIZZAZIONI.AUTORIZRESPONSABILE, AUTORIZZAZIONI.FKIDREGISTRO, AUTORIZZAZIONI.FKIDISTANZA, AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.CODICEMOVIMENTO, AUTORIZZAZIONI.ID FROM  I_ATTIVITA,  AUTORIZZAZIONI,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID and AUTORIZZAZIONI.IDCOMUNE = ISTANZE.IDCOMUNE and AUTORIZZAZIONI.FKIDISTANZA = ISTANZE.CODICEISTANZA;
Create Or Replace View VW_I_ATTIVITAINFORMAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEATTIVITA.CODICEISTANZA, ISTANZEATTIVITA.CODICEATTIVITA, ISTANZEATTIVITA.METRIQ, ISTANZEATTIVITA.NOTE, ISTANZEATTIVITA.IDCOMUNE, ISTANZEATTIVITA.SOFTWARE, ISTANZEATTIVITA.IDATTIVITA FROM  I_ATTIVITA,  ISTANZEATTIVITA WHERE ISTANZEATTIVITA.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZEATTIVITA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
CREATE OR REPLACE VIEW VW_I_ATTIVITALISTA
                                        AS
  SELECT I_ATTIVITA.CODICEISTANZAULTIMA AS I_CODICEISTANZAULTIMA,
    I_ATTIVITA.ID                       AS I_IDATTIVITA,
    I_ATTIVITA.IDCOMUNE,
    I_ATTIVITA.ATTIVA,
    I_ATTIVITA.OPERANTE,
    ISTANZE.SOFTWARE,
    I_ATTIVITA.DENOMINAZIONE,
    ISTANZE.NUMEROISTANZA,
    ISTANZE.CODICERICHIEDENTE,
    T_RICHIEDENTE.NOMINATIVO
    || ' '
    || T_RICHIEDENTE.NOME AS RICHIEDENTE,
    TRIM(T_RICHIEDENTE.CODICEFISCALE
    || ' '
    || T_RICHIEDENTE.PARTITAIVA) AS CF_PIVA_RICHIEDENTE,
    ISTANZE.FKCODICESOGGETTO,
    TIPISOGGETTO.TIPOSOGGETTO,
    ISTANZE.CODICECOMUNE,
    ISTANZE.CODICETITOLARELEGALE,
    TRIM(T_AZIENDARICHIEDENTE.NOMINATIVO
    || ' '
    || T_AZIENDARICHIEDENTE.NOME) AS AZIENDARICHIEDENTE,
    TRIM(T_AZIENDARICHIEDENTE.CODICEFISCALE
    || ' '
    || T_AZIENDARICHIEDENTE.PARTITAIVA) AS CF_PIVA_AZIENDARICHIEDENTE,
    ISTANZESTRADARIO.CODICESTRADARIO,
    STRADARIO.PREFISSO
    || ' '
    || STRADARIO.DESCRIZIONE
    || ','
    || NVL(ISTANZESTRADARIO.CIVICO,'')
    || NVL(ISTANZESTRADARIO.COLORE,'') AS LOCALIZZAZIONE,
    ISTANZESTRADARIO.CIVICO
  FROM I_ATTIVITA,
    ISTANZE,
    ANAGRAFE T_RICHIEDENTE,
    TIPISOGGETTO,
    ANAGRAFE T_AZIENDARICHIEDENTE,
    ISTANZESTRADARIO,
    STRADARIO
  WHERE ISTANZE.IDCOMUNE                     = I_ATTIVITA.IDCOMUNE
  AND ISTANZE.CODICEISTANZA                  = I_ATTIVITA.CODICEISTANZAULTIMA
  AND T_RICHIEDENTE.IDCOMUNE                 = ISTANZE.IDCOMUNE
  AND T_RICHIEDENTE.CODICEANAGRAFE           = ISTANZE.CODICERICHIEDENTE
  AND T_AZIENDARICHIEDENTE.IDCOMUNE(+)       = ISTANZE.IDCOMUNE
  AND T_AZIENDARICHIEDENTE.CODICEANAGRAFE(+) = ISTANZE.CODICETITOLARELEGALE
  AND TIPISOGGETTO.IDCOMUNE(+)               = ISTANZE.IDCOMUNE
  AND TIPISOGGETTO.CODICETIPOSOGGETTO(+)     = ISTANZE.FKCODICESOGGETTO
  AND ISTANZESTRADARIO.IDCOMUNE              = ISTANZE.IDCOMUNE
  AND ISTANZESTRADARIO.CODICEISTANZA         = ISTANZE.CODICEISTANZA
  AND ISTANZESTRADARIO.PRIMARIO              = 1
  AND STRADARIO.IDCOMUNE                     = ISTANZESTRADARIO.IDCOMUNE
  AND STRADARIO.CODICESTRADARIO              = ISTANZESTRADARIO.CODICESTRADARIO
WITH READ ONLY;
Create Or Replace View VW_I_ATTIVITALOCALIZZAZIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZESTRADARIO.ID, ISTANZESTRADARIO.CODICEISTANZA, ISTANZESTRADARIO.CODICESTRADARIO, ISTANZESTRADARIO.CIVICO, ISTANZESTRADARIO.COLORE, ISTANZESTRADARIO.NOTE, ISTANZESTRADARIO.PRIMARIO, ISTANZESTRADARIO.IDCOMUNE, ISTANZESTRADARIO.FRAZIONE, ISTANZESTRADARIO.CIRCOSCRIZIONE, ISTANZESTRADARIO.CAP, ISTANZESTRADARIO.KM, ISTANZESTRADARIO.ESPONENTE, ISTANZESTRADARIO.SCALA, ISTANZESTRADARIO.INTERNO, ISTANZESTRADARIO.ESPONENTEINTERNO, ISTANZESTRADARIO.FABBRICATO, ISTANZESTRADARIO.CODICECIVICO, ISTANZESTRADARIO.FKIDMAPPALE, ISTANZESTRADARIO.VALIDO FROM  I_ATTIVITA,  ISTANZESTRADARIO WHERE ISTANZESTRADARIO.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZESTRADARIO.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
Create Or Replace View VW_I_ATTIVITAMAPPALI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZEMAPPALI.IDMAPPALE, ISTANZEMAPPALI.FOGLIO, ISTANZEMAPPALI.PARTICELLA, ISTANZEMAPPALI.SUB, ISTANZEMAPPALI.FKCODICEISTANZA, ISTANZEMAPPALI.PRIMARIO, ISTANZEMAPPALI.IDCOMUNE, ISTANZEMAPPALI.CODICECATASTO, ISTANZEMAPPALI.SEZIONE, ISTANZEMAPPALI.UNITAIMMOB FROM  I_ATTIVITA,  ISTANZEMAPPALI WHERE ISTANZEMAPPALI.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZEMAPPALI.FKCODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA and ISTANZEMAPPALI.FOGLIO  is not  NULL;
Create Or Replace View VW_I_ATTIVITAORARI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ORARIAPERTURATESTATA.ID, ORARIAPERTURATESTATA.IDCOMUNE, ORARIAPERTURATESTATA.PERIODODA, ORARIAPERTURATESTATA.PERIODOA, ORARIAPERTURATESTATA.CODICEISTANZA, ORARIAPERTURATESTATA.FKTOID FROM  I_ATTIVITA,  ORARIAPERTURATESTATA WHERE ORARIAPERTURATESTATA.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ORARIAPERTURATESTATA.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA;
Create Or Replace View VW_I_ATTIVITASOGGETTICOLLEGATI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, ISTANZERICHIEDENTI.CODICEISTANZA, ISTANZERICHIEDENTI.CODICERICHIEDENTE, ISTANZERICHIEDENTI.CODICETIPOSOGGETTO, ISTANZERICHIEDENTI.IDCOMUNE, ISTANZERICHIEDENTI.CODICEANAGRAFECOLL FROM  I_ATTIVITA,  ISTANZERICHIEDENTI WHERE ISTANZERICHIEDENTI.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA, ISTANZE.CODICEISTANZA, ISTANZE.CODICERICHIEDENTE,  ISTANZE.FKCODICESOGGETTO as CODICETIPOSOGGETTO, ISTANZE.IDCOMUNE,  ISTANZE.CODICETITOLARELEGALE as CODICEANAGRAFECOLL From I_ATTIVITA,  ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA UNION Select I_ATTIVITA.ID as I_IDATTIVITA, ISTANZE.CODICEISTANZA, ISTANZE.CODICETITOLARELEGALE as CODICERICHIEDENTE,  -1 as CODICETIPOSOGGETTO, ISTANZE.IDCOMUNE,  -1 as CODICEANAGRAFECOLL From I_ATTIVITA,  ISTANZE Where ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.CODICEISTANZA = I_ATTIVITA.CODICEISTANZAULTIMA and ISTANZE.CODICETITOLARELEGALE is not null;
Create Or Replace View VW_ISTANZECONCESSIONILISTA as SELECT AUTORIZZAZIONI.IDCOMUNE, AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AS ICONC_CODICECAUSALE, AUTORIZZAZIONI.DATA_CESSAZIONE AS DATA_STORICO, ISTANZE.SOFTWARE, ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA, ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA , istanze.codicerichiedente AS ist_codicerichiedente , AUTORIZZAZIONI.ID AS CONC_ID , AUTORIZZAZIONI.AUTORIZNUMERO AS CONC_NUMERO , AUTORIZZAZIONI.AUTORIZDATA AS CONC_DATARILASCIO , AUTORIZZAZIONI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA , AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO , CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO , AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA , AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA , AUTORIZZAZIONI.FLAG_ATTIVA AS CONC_ATTIVA , AUTORIZZAZIONI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE , TITOLARE.NOMINATIVO || ' ' || TITOLARE.NOME AS CONC_TITOLARE , titolare.codicefiscale as conc_tit_cf , TITOLARE.PARTITAIVA AS CONC_TIT_PIVA , TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO , AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA , AUT_COLLEGATA.AUTORIZDATA , AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO , IST_RICHIEDENTE.NOMINATIVO || ' ' || IST_RICHIEDENTE.NOME AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, IST_AZIENDA.NOMINATIVO || ' ' || IST_AZIENDA.NOME AS IST_NOMINATIVOAZIENDA , IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, ist_richiedente.codicefiscale as ist_codicefiscale , IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA , CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE , AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO , AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AS CONC_IDMERCATO , MERCATI.DESCRIZIONE AS CONC_MERCATO , MERCATI.ATTIVO AS MERC_ATTIVO , AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO , MERCATI_D.CODICEPOSTEGGIO AS CONC_POSTEGGIO , MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA , MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA , MERCATI_D.SUPERFICIE AS CONC_POS_SUPERFICIE , MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO , POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO , AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO , MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO , MERCATI_USO.PESO AS PESO_MERCATO , MERCATI_USO.FKCODICEUSO AS MERC_IDUSO FROM AUTORIZZAZIONI, AUTORIZZAZIONI_CONCESSIONI, AUTORIZZAZIONI AUT_COLLEGATA, CONCESSIONITIPI, TIPOLOGIAREGISTRI, ANAGRAFE TITOLARE, CONCESSIONICAUSALI CAUS_ATTUALE, CONCESSIONICAUSALI CAUS_STORICO, ISTANZE, ANAGRAFE IST_RICHIEDENTE, MERCATI, MERCATI_D, POSTEGGITIPOSPAZIO, MERCATI_USO, ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI.id =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND AUT_COLLEGATA.IDCOMUNE(+) =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUT_COLLEGATA.id(+) =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA AND CONCESSIONITIPI.TIPOCONCESSIONE =AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TIPOLOGIAREGISTRI.IDCOMUNE(+) =AUTORIZZAZIONI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID(+) =AUTORIZZAZIONI.FKIDREGISTRO AND TITOLARE.IDCOMUNE =AUTORIZZAZIONI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE =AUTORIZZAZIONI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE =AUTORIZZAZIONI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE =AUTORIZZAZIONI.FK_CAUSALE_ACQUISIZIONE AND CAUS_STORICO.IDCOMUNE(+) =AUTORIZZAZIONI.IDCOMUNE AND CAUS_STORICO.CODICECAUSALE(+) =AUTORIZZAZIONI.FK_CAUSALE_CESSAZIONE AND ISTANZE.IDCOMUNE =AUTORIZZAZIONI.IDCOMUNE AND ISTANZE.CODICEISTANZA =AUTORIZZAZIONI.FKIDISTANZA AND IST_RICHIEDENTE.IDCOMUNE =ISTANZE.IDCOMUNE AND IST_RICHIEDENTE.CODICEANAGRAFE =ISTANZE.CODICERICHIEDENTE AND MERCATI.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI.CODICEMERCATO =AUTORIZZAZIONI_CONCESSIONI.FK_CODICEMERCATO AND MERCATI_D.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_D.IDPOSTEGGIO =AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AND POSTEGGITIPOSPAZIO.IDCOMUNE(+) =MERCATI_D.IDCOMUNE AND POSTEGGITIPOSPAZIO.CODICE(+) =MERCATI_D.FKCODICETIPOSPAZIO AND MERCATI_USO.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND MERCATI_USO.ID =AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AND IST_AZIENDA.IDCOMUNE(+) =ISTANZE.IDCOMUNE AND IST_AZIENDA.CODICEANAGRAFE(+) =ISTANZE.CODICETITOLARELEGALE UNION SELECT AUTORIZZAZIONI_SUBENTRI.IDCOMUNE , autorizzazioni_subentri.fk_causale_acquisizione as iconc_codicecausale, AUTORIZZAZIONI_SUBENTRI.DATA_CESSAZIONE AS DATA_STORICO , ISTANZE.SOFTWARE , ISTANZE.CODICEISTANZA AS IST_CODICEISTANZA , ISTANZE.NUMEROISTANZA AS IST_NUMEROISTANZA , ISTANZE.CODICERICHIEDENTE AS IST_CODICERICHIEDENTE , autorizzazioni_subentri.id as conc_id , AUTORIZZAZIONI_SUBENTRI.AUTORIZNUMERO AS CONC_NUMERO , AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS CONC_DATARILASCIO , AUTORIZZAZIONI_SUBENTRI.AUTORIZDATA AS DATARILASCIO, AUTORIZZAZIONI_CONCESSIONI.DATASCADENZA AS CONC_DATASCADENZA , AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AS CONC_CODICETIPO , CONCESSIONITIPI.DESCRIZIONE AS CONC_TIPO , AUTORIZZAZIONI_CONCESSIONI.STAGIONALEA AS CONC_STAGIONALEA , AUTORIZZAZIONI_CONCESSIONI.STAGIONALEDA AS CONC_STAGIONALEDA , 0 AS CONC_ATTIVA , AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AS CONC_CODICETITOLARE , TITOLARE.NOMINATIVO || ' ' || TITOLARE.NOME AS CONC_TITOLARE , titolare.codicefiscale as conc_tit_cf , TITOLARE.PARTITAIVA AS CONC_TIT_PIVA , TITOLARE.TIPOANAGRAFE AS CONC_TIT_TIPOANAGRAFE, AUT_COLLEGATA.AUTORIZNUMERO AS AUT_NUMERO , AUT_COLLEGATA.AUTORIZDATA AS AUT_DATA , AUT_COLLEGATA.AUTORIZDATA , AUT_COLLEGATA.FKIDREGISTRO AS AUT_CODREGISTRO, TIPOLOGIAREGISTRI.TR_DESCRIZIONE AS AUT_REGISTRO , IST_RICHIEDENTE.NOMINATIVO || ' ' || IST_RICHIEDENTE.NOME AS IST_NOMINATIVO, IST_RICHIEDENTE.TIPOANAGRAFE AS IST_RIC_TIPOANAGRAFE, IST_AZIENDA.NOMINATIVO || ' ' || IST_AZIENDA.NOME AS IST_NOMINATIVOAZIENDA , IST_AZIENDA.TIPOANAGRAFE AS IST_AZI_TIPOANAGRAFE, IST_RICHIEDENTE.CODICEFISCALE AS IST_CODICEFISCALE , IST_RICHIEDENTE.PARTITAIVA AS IST_PARTITAIVA , CAUS_ATTUALE.DESCRIZIONE AS ICONC_CAUSALE , AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_CESSAZIONE AS ICONC_CODICECAUSALESTORICO, CAUS_STORICO.DESCRIZIONE AS ICONC_CAUSALESTORICO , autorizzazioni_concessioni.fk_codicemercato as conc_idmercato , MERCATI.DESCRIZIONE AS CONC_MERCATO , MERCATI.ATTIVO AS MERC_ATTIVO , AUTORIZZAZIONI_CONCESSIONI.FK_IDPOSTEGGIO AS CONC_IDPOSTEGGIO , mercati_d.codiceposteggio as conc_posteggio , MERCATI_D.LARGHEZZA AS CONC_POS_LARGHEZZA , MERCATI_D.LUNGHEZZA AS CONC_POS_LUNGHEZZA , mercati_d.superficie as conc_pos_superficie , MERCATI_D.FKCODICETIPOSPAZIO AS POST_IDTIPOSPAZIO , POSTEGGITIPOSPAZIO.TIPOSPAZIO AS POST_TIPOSPAZIO , AUTORIZZAZIONI_CONCESSIONI.FK_IDMERCATIUSO AS CONC_IDMERCATIUSO , MERCATI_USO.DESCRIZIONE AS CONC_DESCRIZIONEUSO , MERCATI_USO.PESO AS PESO_MERCATO , MERCATI_USO.FKCODICEUSO AS MERC_IDUSO FROM AUTORIZZAZIONI_SUBENTRI , AUTORIZZAZIONI_CONCESSIONI , AUTORIZZAZIONI AUT_COLLEGATA, CONCESSIONITIPI , TIPOLOGIAREGISTRI , ANAGRAFE TITOLARE , CONCESSIONICAUSALI CAUS_ATTUALE, CONCESSIONICAUSALI CAUS_STORICO, ISTANZE , ANAGRAFE IST_RICHIEDENTE , MERCATI , MERCATI_D , POSTEGGITIPOSPAZIO , MERCATI_USO , ANAGRAFE IST_AZIENDA WHERE AUTORIZZAZIONI_SUBENTRI.IDCOMUNE =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUTORIZZAZIONI_SUBENTRI.id =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_ATTUALE AND AUT_COLLEGATA.IDCOMUNE(+) =AUTORIZZAZIONI_CONCESSIONI.IDCOMUNE AND AUT_COLLEGATA.id(+) =AUTORIZZAZIONI_CONCESSIONI.FK_IDAUT_COLLEGATA AND CONCESSIONITIPI.TIPOCONCESSIONE =AUTORIZZAZIONI_CONCESSIONI.FK_TIPOCONCESSIONE AND TIPOLOGIAREGISTRI.IDCOMUNE(+) =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TIPOLOGIAREGISTRI.TR_ID(+) =AUTORIZZAZIONI_SUBENTRI.FKIDREGISTRO AND TITOLARE.IDCOMUNE =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND TITOLARE.CODICEANAGRAFE =AUTORIZZAZIONI_SUBENTRI.FK_CODICEANAGRAFE AND CAUS_ATTUALE.IDCOMUNE =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE AND CAUS_ATTUALE.CODICECAUSALE =AUTORIZZAZIONI_SUBENTRI.FK_CAUSALE_ACQUISIZIONE AND CAUS_STORICO.IDCOMUNE(+) =AUTORIZZAZIONI_SUBENTRI.IDCOMUNE ;
Create Or Replace View VW_CONCESSIONILISTA as SELECT IDCOMUNE, SOFTWARE, CONC_ID, CONC_NUMERO, CONC_DATARILASCIO, CONC_DATASCADENZA, CONC_CODICETIPO, CONC_TIPO, CONC_STAGIONALEA, CONC_STAGIONALEDA, CONC_ATTIVA, CONC_CODICETITOLARE, CONC_TITOLARE, CONC_TIT_CF, CONC_TIT_PIVA, CONC_TIT_TIPOANAGRAFE, AUT_NUMERO, AUT_DATA, AUT_CODREGISTRO, AUT_REGISTRO, IST_CODICEISTANZA, IST_NUMEROISTANZA, IST_CODICERICHIEDENTE, IST_NOMINATIVO, IST_CODICEFISCALE, IST_PARTITAIVA, IST_RIC_TIPOANAGRAFE, ICONC_CODICECAUSALE, ICONC_CAUSALE, ICONC_CODICECAUSALESTORICO, ICONC_CAUSALESTORICO, CONC_IDMERCATO, CONC_MERCATO, MERC_ATTIVO, CONC_IDPOSTEGGIO, CONC_POSTEGGIO, CONC_POS_LARGHEZZA, CONC_POS_LUNGHEZZA, CONC_POS_SUPERFICIE, POST_IDTIPOSPAZIO, POST_TIPOSPAZIO, CONC_IDMERCATIUSO, CONC_DESCRIZIONEUSO, PESO_MERCATO, MERC_IDUSO FROM  VW_ISTANZECONCESSIONILISTA;
CREATE OR REPLACE View VW_I_ATTIVITACONCESSIONI as SELECT I_ATTIVITA.ID as I_IDATTIVITA, VW_CONCESSIONILISTA.IDCOMUNE, VW_CONCESSIONILISTA.SOFTWARE, VW_CONCESSIONILISTA.CONC_ID, VW_CONCESSIONILISTA.CONC_NUMERO, VW_CONCESSIONILISTA.CONC_DATARILASCIO, VW_CONCESSIONILISTA.CONC_DATASCADENZA, VW_CONCESSIONILISTA.CONC_CODICETIPO, VW_CONCESSIONILISTA.CONC_TIPO, VW_CONCESSIONILISTA.CONC_STAGIONALEA, VW_CONCESSIONILISTA.CONC_STAGIONALEDA, VW_CONCESSIONILISTA.CONC_ATTIVA, VW_CONCESSIONILISTA.CONC_CODICETITOLARE, VW_CONCESSIONILISTA.CONC_TITOLARE, VW_CONCESSIONILISTA.CONC_TIT_CF, VW_CONCESSIONILISTA.CONC_TIT_PIVA, VW_CONCESSIONILISTA.CONC_TIT_TIPOANAGRAFE, VW_CONCESSIONILISTA.AUT_NUMERO, VW_CONCESSIONILISTA.AUT_DATA, VW_CONCESSIONILISTA.AUT_CODREGISTRO, VW_CONCESSIONILISTA.AUT_REGISTRO, VW_CONCESSIONILISTA.IST_CODICEISTANZA, VW_CONCESSIONILISTA.IST_NUMEROISTANZA, VW_CONCESSIONILISTA.IST_CODICERICHIEDENTE, VW_CONCESSIONILISTA.IST_NOMINATIVO, VW_CONCESSIONILISTA.IST_CODICEFISCALE, VW_CONCESSIONILISTA.IST_PARTITAIVA, VW_CONCESSIONILISTA.IST_RIC_TIPOANAGRAFE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALE, VW_CONCESSIONILISTA.ICONC_CAUSALE, VW_CONCESSIONILISTA.ICONC_CODICECAUSALESTORICO, VW_CONCESSIONILISTA.ICONC_CAUSALESTORICO, VW_CONCESSIONILISTA.CONC_IDMERCATO, VW_CONCESSIONILISTA.CONC_MERCATO, VW_CONCESSIONILISTA.MERC_ATTIVO, VW_CONCESSIONILISTA.CONC_IDPOSTEGGIO, VW_CONCESSIONILISTA.CONC_POSTEGGIO, VW_CONCESSIONILISTA.CONC_POS_LARGHEZZA, VW_CONCESSIONILISTA.CONC_POS_LUNGHEZZA, VW_CONCESSIONILISTA.CONC_POS_SUPERFICIE, VW_CONCESSIONILISTA.POST_IDTIPOSPAZIO, VW_CONCESSIONILISTA.POST_TIPOSPAZIO, VW_CONCESSIONILISTA.CONC_IDMERCATIUSO, VW_CONCESSIONILISTA.CONC_DESCRIZIONEUSO, VW_CONCESSIONILISTA.PESO_MERCATO, VW_CONCESSIONILISTA.MERC_IDUSO FROM  I_ATTIVITA,  VW_CONCESSIONILISTA,  ISTANZE WHERE ISTANZE.IDCOMUNE = I_ATTIVITA.IDCOMUNE and ISTANZE.FK_IDI_ATTIVITA = I_ATTIVITA.ID and VW_CONCESSIONILISTA.IDCOMUNE = ISTANZE.IDCOMUNE and VW_CONCESSIONILISTA.IST_CODICEISTANZA = ISTANZE.CODICEISTANZA;
CREATE OR REPLACE View VW_ISTANZEDYN2_DATI as SELECT istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id as idmodello, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale, NULL as tipotesto, NULL as testo, istanzedyn2dati.indice, dyn2_campi.id as idcampo, dyn2_campi.nomecampo, istanzedyn2dati.valore FROM dyn2_campi LEFT OUTER JOIN istanzedyn2dati ON dyn2_campi.idcomune=istanzedyn2dati.idcomune  AND dyn2_campi.id=istanzedyn2dati.fk_d2c_id, dyn2_modellid, istanzedyn2modellit WHERE dyn2_campi.idcomune = dyn2_modellid.idcomune AND dyn2_campi.id = dyn2_modellid.fk_d2c_id AND dyn2_modellid.idcomune = istanzedyn2modellit.idcomune AND dyn2_modellid.fk_d2mt_id = istanzedyn2modellit.fk_d2mt_id  ORDER BY istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale;
Create Or Replace View VW_ISTANZEDYN2_DATIMODELLO as select istanzedyn2modellit.idcomune, istanzedyn2modellit.codiceistanza, istanzedyn2modellit.fk_d2mt_id as idmodello, dyn2_modellid.posverticale, dyn2_modellid.posorizzontale, dyn2_modellidtesti.fk_d2btt_id as tipotesto, dyn2_modellidtesti.testo, null as indice, null as idcampo, null as nomecampo, NULL as valore from  dyn2_modellid, dyn2_modellidtesti, istanzedyn2modellit Where dyn2_modellidtesti.idcomune(+)=dyn2_modellid.idcomune and dyn2_modellidtesti.id(+)=dyn2_modellid.fk_d2mdt_id and dyn2_modellid.idcomune=istanzedyn2modellit.idcomune and dyn2_modellid.fk_d2mt_id=istanzedyn2modellit.fk_d2mt_id UNION select idcomune, codiceistanza, idmodello, posverticale, posorizzontale, tipotesto, testo, indice, idcampo, nomecampo, To_Char(substr(valore,1,4000)) from vw_istanzedyn2_dati;
CREATE OR REPLACE View VW_ISTANZEONERI as SELECT istanze.idcomune, istanze.software, istanzeoneri.codiceistanza, istanzeoneri.id, istanzeoneri.fkidtipocausale as causale, tipicausalioneri.co_descrizione as causaleDescrizione, istanzeoneri.data as dataregistrazione, istanzeoneri.prezzo as importo, istanzeoneri.numerorata, istanzeoneri.datascadenza as datascadenza, istanzeoneri.datapagamento as dataincasso, istanzeoneri.fkmodalitapagamento as codicemodalitaincasso, tipimodalitapagamento.mp_descrestesa as modalitaincasso, istanzeoneri.docriferimento as riferimentiincasso FROM istanzeoneri LEFT OUTER JOIN tipimodalitapagamento ON istanzeoneri.idcomune=tipimodalitapagamento.idcomune  AND istanzeoneri.fkmodalitapagamento=tipimodalitapagamento.mp_id, istanze, tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND istanzeoneri.flentratauscita = 1 ;
CREATE OR REPLACE View VW_ISTANZEORARI as SELECT ORARIAPERTURATESTATA.ID, ORARIAPERTURATESTATA.IDCOMUNE, ORARIAPERTURATESTATA.PERIODODA, ORARIAPERTURATESTATA.PERIODOA, ORARIAPERTURATESTATA.CODICEISTANZA, ORARIAPERTURATESTATA.FKTOID, ORARIAPERTURA_LUN.OA_DALLEORE as LUN_DALLEORE, ORARIAPERTURA_LUN.OA_ALLEORE as LUN_ALLEORE, ORARIAPERTURA_LUN.OA_DALLEOREPOM as LUN_DALLEOREPOM, ORARIAPERTURA_LUN.OA_ALLEOREPOM as LUN_ALLEOREPOM, ORARIAPERTURA_LUN.OA_FKIDORARIO as LUN_FKIDORARIO, TIPIAPERTURA_LUN.TA_DESCRIZIONE as LUN_CHIUSURA, ORARIAPERTURA_MAR.OA_DALLEORE as MAR_DALLEORE, ORARIAPERTURA_MAR.OA_ALLEORE as MAR_ALLEORE, ORARIAPERTURA_MAR.OA_DALLEOREPOM as MAR_DALLEOREPOM, ORARIAPERTURA_MAR.OA_ALLEOREPOM as MAR_ALLEOREPOM, ORARIAPERTURA_MAR.OA_FKIDORARIO as MAR_FKIDORARIO, TIPIAPERTURA_MAR.TA_DESCRIZIONE as MAR_CHIUSURA, ORARIAPERTURA_MER.OA_DALLEORE as MER_DALLEORE, ORARIAPERTURA_MER.OA_ALLEORE as MER_ALLEORE, ORARIAPERTURA_MER.OA_DALLEOREPOM as MER_DALLEOREPOM, ORARIAPERTURA_MER.OA_ALLEOREPOM as MER_ALLEOREPOM, ORARIAPERTURA_MER.OA_FKIDORARIO as MER_FKIDORARIO, TIPIAPERTURA_MER.TA_DESCRIZIONE as MER_CHIUSURA, ORARIAPERTURA_GIO.OA_DALLEORE as GIO_DALLEORE, ORARIAPERTURA_GIO.OA_ALLEORE as GIO_ALLEORE, ORARIAPERTURA_GIO.OA_DALLEOREPOM as GIO_DALLEOREPOM, ORARIAPERTURA_GIO.OA_ALLEOREPOM as GIO_ALLEOREPOM, ORARIAPERTURA_GIO.OA_FKIDORARIO as GIO_FKIDORARIO, TIPIAPERTURA_GIO.TA_DESCRIZIONE as GIO_CHIUSURA, ORARIAPERTURA_VEN.OA_DALLEORE as VEN_DALLEORE, ORARIAPERTURA_VEN.OA_ALLEORE as VEN_ALLEORE, ORARIAPERTURA_VEN.OA_DALLEOREPOM as VEN_DALLEOREPOM, ORARIAPERTURA_VEN.OA_ALLEOREPOM as VEN_ALLEOREPOM, ORARIAPERTURA_VEN.OA_FKIDORARIO as VEN_FKIDORARIO, TIPIAPERTURA_VEN.TA_DESCRIZIONE as VEN_CHIUSURA, ORARIAPERTURA_SAB.OA_DALLEORE as SAB_DALLEORE, ORARIAPERTURA_SAB.OA_ALLEORE as SAB_ALLEORE, ORARIAPERTURA_SAB.OA_DALLEOREPOM as SAB_DALLEOREPOM, ORARIAPERTURA_SAB.OA_ALLEOREPOM as SAB_ALLEOREPOM, ORARIAPERTURA_SAB.OA_FKIDORARIO as SAB_FKIDORARIO, TIPIAPERTURA_SAB.TA_DESCRIZIONE as SAB_CHIUSURA, ORARIAPERTURA_DOM.OA_DALLEORE as DOM_DALLEORE, ORARIAPERTURA_DOM.OA_ALLEORE as DOM_ALLEORE, ORARIAPERTURA_DOM.OA_DALLEOREPOM as DOM_DALLEOREPOM, ORARIAPERTURA_DOM.OA_ALLEOREPOM as DOM_ALLEOREPOM, ORARIAPERTURA_DOM.OA_FKIDORARIO as DOM_FKIDORARIO, TIPIAPERTURA_DOM.TA_DESCRIZIONE as DOM_CHIUSURA FROM ORARIAPERTURATESTATA LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_LUN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_LUN ON ORARIAPERTURA_LUN.IDCOMUNE=TIPIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURA_LUN.OA_FKIDORARIO=TIPIAPERTURA_LUN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_LUN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_LUN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MAR LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MAR ON ORARIAPERTURA_MAR.IDCOMUNE=TIPIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURA_MAR.OA_FKIDORARIO=TIPIAPERTURA_MAR.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MAR.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MAR.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_MER LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_MER ON ORARIAPERTURA_MER.IDCOMUNE=TIPIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURA_MER.OA_FKIDORARIO=TIPIAPERTURA_MER.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_MER.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_MER.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_GIO LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_GIO ON ORARIAPERTURA_GIO.IDCOMUNE=TIPIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURA_GIO.OA_FKIDORARIO=TIPIAPERTURA_GIO.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_GIO.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_GIO.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_VEN LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_VEN ON ORARIAPERTURA_VEN.IDCOMUNE=TIPIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURA_VEN.OA_FKIDORARIO=TIPIAPERTURA_VEN.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_VEN.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_VEN.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_SAB LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_SAB ON ORARIAPERTURA_SAB.IDCOMUNE=TIPIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURA_SAB.OA_FKIDORARIO=TIPIAPERTURA_SAB.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_SAB.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_SAB.OA_FKIDTESTATA  LEFT OUTER JOIN ORARIAPERTURA ORARIAPERTURA_DOM LEFT OUTER JOIN TIPIAPERTURA TIPIAPERTURA_DOM ON ORARIAPERTURA_DOM.IDCOMUNE=TIPIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURA_DOM.OA_FKIDORARIO=TIPIAPERTURA_DOM.TA_ID ON ORARIAPERTURATESTATA.IDCOMUNE=ORARIAPERTURA_DOM.IDCOMUNE  AND ORARIAPERTURATESTATA.ID=ORARIAPERTURA_DOM.OA_FKIDTESTATA WHERE ( ORARIAPERTURA_LUN.OA_FKIDGIORNO = 1 or ORARIAPERTURA_LUN.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MAR.OA_FKIDGIORNO = 2 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_MER.OA_FKIDGIORNO = 3 or ORARIAPERTURA_MER.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_GIO.OA_FKIDGIORNO = 4 or ORARIAPERTURA_GIO.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_VEN.OA_FKIDGIORNO = 5 or ORARIAPERTURA_MAR.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_SAB.OA_FKIDGIORNO = 6 or ORARIAPERTURA_SAB.OA_FKIDGIORNO  is  NULL ) AND ( ORARIAPERTURA_DOM.OA_FKIDGIORNO = 7 or ORARIAPERTURA_DOM.OA_FKIDGIORNO  is  NULL ) ;
CREATE OR REPLACE View VW_ISTANZEPROCEDIMENTI as SELECT ISTANZEPROCEDIMENTI.CODICEISTANZA, ISTANZEPROCEDIMENTI.CODICEINVENTARIO, INVENTARIOPROCEDIMENTI.PROCEDIMENTO, ISTANZEPROCEDIMENTI.PERPROVVEDIMENTO, ISTANZEPROCEDIMENTI.ACQUISITO, ISTANZEPROCEDIMENTI.COSTORICHIESTO, ISTANZEPROCEDIMENTI.COSTOPAGATO, ISTANZEPROCEDIMENTI.PROC_NUM, ISTANZEPROCEDIMENTI.PROT_NUM, ISTANZEPROCEDIMENTI.PROC_DEL, ISTANZEPROCEDIMENTI.PROT_DEL, ISTANZEPROCEDIMENTI.DATAATTIVAZIONE, ISTANZEPROCEDIMENTI.IDCOMUNE, ISTANZEPROCEDIMENTI.ELIMINATO, ISTANZEPROCEDIMENTI.FLAG_COMMISSIONE FROM  ISTANZEPROCEDIMENTI,  INVENTARIOPROCEDIMENTI WHERE INVENTARIOPROCEDIMENTI.IDCOMUNE = ISTANZEPROCEDIMENTI.IDCOMUNE and INVENTARIOPROCEDIMENTI.CODICEINVENTARIO = ISTANZEPROCEDIMENTI.CODICEINVENTARIO;
CREATE OR REPLACE View VW_ISTANZESOGGETTICOLLEGATI as SELECT 'S' as TIPOLOGIA,ISTANZERICHIEDENTI.CODICEISTANZA,ISTANZERICHIEDENTI.CODICERICHIEDENTE,ISTANZERICHIEDENTI.CODICEINVITATO,ISTANZERICHIEDENTI.CODICETIPOSOGGETTO,ISTANZERICHIEDENTI.IDCOMUNE,ISTANZERICHIEDENTI.CODICEANAGRAFECOLL,NVL(ISTANZERICHIEDENTI.DESCRSOGGETTO, TIPISOGGETTO.TIPOSOGGETTO ) as DESCRSOGGETTO,ISTANZERICHIEDENTI.CODICEPROCURATORE,ISTANZE.FK_IDI_ATTIVITA FROM  ISTANZERICHIEDENTI, ISTANZE, TIPISOGGETTO WHERE TIPISOGGETTO.IDCOMUNE = ISTANZERICHIEDENTI.IDCOMUNE and TIPISOGGETTO.CODICETIPOSOGGETTO = ISTANZERICHIEDENTI.CODICETIPOSOGGETTO and ISTANZERICHIEDENTI.IDCOMUNE = ISTANZE.IDCOMUNE and ISTANZERICHIEDENTI.CODICEISTANZA = ISTANZE.CODICEISTANZA UNION SELECT 'R' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICERICHIEDENTE,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,NVL(TIPISOGGETTO.TIPOSOGGETTO, 'RICHIEDENTE' ) as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM ISTANZE LEFT OUTER JOIN TIPISOGGETTO ON ISTANZE.IDCOMUNE=TIPISOGGETTO.IDCOMUNE  AND ISTANZE.FKCODICESOGGETTO=TIPISOGGETTO.CODICETIPOSOGGETTO UNION SELECT 'A' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICETITOLARELEGALE,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,'RAGIONE SOCIALE' as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICETITOLARELEGALE  is  NULL UNION SELECT 'T' as TIPOLOGIA,ISTANZE.CODICEISTANZA,ISTANZE.CODICEPROFESSIONISTA,NULL as CODICEINVITATO,NULL as CODICETIPOSOGGETTO,ISTANZE.IDCOMUNE,NULL as CODICEANAGRAFECOLL,'PROFESSIONISTA' as DESCRSOGGETTO,NULL as CODICEPROCURATORE,FK_IDI_ATTIVITA FROM  ISTANZE WHERE NOT CODICEPROFESSIONISTA  is  NULL;
Create Or Replace View VW_LISTAPRATICHE as SELECT istanze.codicecomune , istanze.idcomune , istanze.software AS software , software.descrizionelunga AS descsoftware , istanze.codiceistanza AS idpratica , istanze.numeroistanza AS numeropratica , TO_CHAR(istanze.data,'DD/MM/YYYY') AS datapresentazione , TO_CHAR(istanze.data,'YYYY') AS annopresentazione , TO_CHAR(istanze.data,'MM') AS mesepresentazione , istanze.numeroprotocollo , TO_CHAR(istanze.dataprotocollo,'DD/MM/YYYY') AS dataprotocollo , istanze.codiceinterventoproc AS codiceintervento , vw_alberoproc.sc_descrizione AS descrizioneintervento, tipiprocedure.codiceprocedura , tipiprocedure.procedura , istanze.lavori AS oggetto , UPPER(istanze.lavori) AS oggettou , istanze.chiusura AS codstatopratica , stato AS statopratica , responsabili.responsabile , responsabili.telefonolavoro AS responsabile_telefono , NVL(stradario.codviario,stradario.codicestradario) AS pr_codviario , stradario.prefisso || ' ' || stradario.descrizione AS pr_indirizzo , istanzestradario.CODICECIVICO AS pr_codcivico , istanze.civico AS pr_civico , istanze.codicearea AS codicezonizzazione, aree.denominazione AS zonizzazione , anagrafe.codiceanagrafe AS CodiceRichiedente , NVL(anagrafe.codicefiscale, '') AS codicefiscale , NVL(anagrafe.partitaiva, '') AS partitaiva , anagrafe.nominativo || ' ' || anagrafe.nome AS nominativo, anagrafe.indirizzo , anagrafe.cap , anagrafe.citta AS localita , comuneresidenza.comune AS citta , comuneresidenza.provincia , tipisoggetto.tiposoggetto AS tiporapporto , catasto.descrizione AS tipocatasto , istanzemappali.foglio , istanzemappali.particella , istanzemappali.sub , tecnico.codiceanagrafe AS tec_codice , tecnico.nominativo || ' ' || tecnico.nome AS tec_nominativo , NVL(tecnico.codicefiscale, '') AS tec_codicefiscale, NVL(tecnico.partitaiva, '') AS tec_partitaiva , azienda.codiceanagrafe AS az_codice , azienda.nominativo || ' ' || azienda.nome AS az_nominativo , NVL(azienda.codicefiscale, '') AS az_codicefiscale, NVL(azienda.partitaiva, '') AS az_partitaiva, istruttori.responsabile AS istruttore, istruttori.telefonolavoro AS istruttore_telefono, operatori.responsabile AS operatore, operatori.telefonolavoro AS operatore_telefono FROM istanze, software, anagrafe, istanzestradario, stradario, istanzemappali, vw_alberoproc, responsabili, comuni comuneresidenza, tipisoggetto, statiistanza, anagrafe tecnico, anagrafe azienda, aree, catasto, tipiprocedure, responsabili istruttori, responsabili operatori WHERE software.codice = istanze.software AND anagrafe.idcomune = istanze.idcomune AND anagrafe.codiceanagrafe = istanze.codicerichiedente AND tecnico.idcomune(+) =istanze.idcomune AND tecnico.codiceanagrafe(+) =istanze.codiceprofessionista AND azienda.idcomune(+) =istanze.idcomune AND azienda.codiceanagrafe(+) =istanze.codicetitolarelegale AND statiistanza.idcomune = istanze.idcomune AND statiistanza.software = istanze.software AND statiistanza.codicestato = istanze.chiusura AND istanzestradario.idcomune = istanze.idcomune AND istanzestradario.codiceistanza = istanze.codiceistanza AND istanzestradario.primario = 1 AND stradario.idcomune = istanzestradario.idcomune AND stradario.codicestradario = istanzestradario.codicestradario AND istanzemappali.idcomune(+) =istanze.idcomune AND istanzemappali.fkcodiceistanza(+) =istanze.codiceistanza AND istanzemappali.primario = 1 AND vw_alberoproc.idcomune = istanze.idcomune AND vw_alberoproc.sc_id = istanze.codiceinterventoproc AND responsabili.idcomune(+) =istanze.idcomune AND responsabili.codiceresponsabile(+)=istanze.codiceresponsabileproc AND comuneresidenza.codicecomune(+) =anagrafe.comuneresidenza AND tipisoggetto.idcomune(+) =istanze.idcomune AND tipisoggetto.codicetiposoggetto(+)=istanze.fkcodicesoggetto AND aree.idcomune(+) =istanze.idcomune AND aree.codicearea(+) =istanze.codicearea AND catasto.codice(+) =istanzemappali.codicecatasto AND tipiprocedure.idcomune(+) =istanze.idcomune AND tipiprocedure.codiceprocedura(+) =istanze.codiceprocedura AND istruttori.idcomune(+) =istanze.idcomune AND istruttori.codiceresponsabile(+) =istanze.codiceistruttore AND operatori.idcomune(+) =istanze.idcomune AND operatori.codiceresponsabile(+) =istanze.codiceresponsabile;
CREATE OR REPLACE View VW_ONERIREGULUS as SELECT istanzeoneri.idcomune, istanzeoneri.fkidtipocausale, count(istanzeoneri.numerorata) as numerorate, istanzeoneri.codiceistanza, sum(istanzeoneri.prezzo) as importo, istanze.codicerichiedente as richiedente, anagrafe.codicefiscale as codifiscale, anagrafe.partitaiva as partitaiva, impresa.codicefiscale as codifiscale_impresa, impresa.partitaiva as partitaiva_impresa, tipicausalioneri.pagamentiregulus, tipicausalioneri.fkidcausalebollo, istanzeoneri.nr_documento FROM istanze LEFT OUTER JOIN anagrafe impresa ON istanze.idcomune = impresa.idcomune AND istanze.codicetitolarelegale = impresa.codiceanagrafe, istanzeoneri, anagrafe, tipicausalioneri WHERE istanzeoneri.idcomune = istanze.idcomune AND istanzeoneri.codiceistanza = istanze.codiceistanza AND istanze.idcomune = anagrafe.idcomune AND istanze.codicerichiedente = anagrafe.codiceanagrafe AND tipicausalioneri.idcomune = istanzeoneri.idcomune AND tipicausalioneri.co_id = istanzeoneri.fkidtipocausale AND tipicausalioneri.pagamentiregulus = 1  GROUP BY istanzeoneri.fkidtipocausale, istanzeoneri.codiceistanza, istanzeoneri.idcomune, istanze.codicerichiedente, anagrafe.codicefiscale, anagrafe.partitaiva, impresa.codicefiscale, impresa.partitaiva, tipicausalioneri.pagamentiregulus, tipicausalioneri.fkidcausalebollo, istanzeoneri.nr_documento;
CREATE OR REPLACE View VW_POSTEGGIMERCATOUSO as SELECT mercati.idcomune, mercati.codicemercato, mercati_uso.id as iduso, mercati_d.idposteggio FROM  mercati,  mercati_d,  mercati_uso WHERE mercati_uso.idcomune = mercati.idcomune and mercati_uso.fkcodicemercato = mercati.codicemercato and mercati.idcomune = mercati_d.idcomune and mercati.codicemercato = mercati_d.fkcodicemercato;
CREATE OR REPLACE View VW_POSTEGGICONCESSIONI as SELECT vw_posteggimercatouso.IDCOMUNE, vw_posteggimercatouso.CODICEMERCATO, vw_posteggimercatouso.IDUSO, vw_posteggimercatouso.IDPOSTEGGIO, vw_concessioniattive.codiceconcessione, vw_concessioniattive.codiceistanza, vw_concessioniattive.codiceoccupante, vw_concessioniattive.codicetitolare FROM vw_posteggimercatouso LEFT OUTER JOIN vw_concessioniattive ON vw_posteggimercatouso.idcomune=vw_concessioniattive.idcomune  AND vw_posteggimercatouso.codicemercato=vw_concessioniattive.fk_codicemercato  AND vw_posteggimercatouso.iduso=vw_concessioniattive.fk_idmercatiuso  AND vw_posteggimercatouso.idposteggio=vw_concessioniattive.fk_idposteggio;
CREATE OR REPLACE View VW_POSTEGGICONCESSIONIPRESENZE as SELECT VW_POSTEGGICONCESSIONI.CODICEMERCATO, VW_POSTEGGICONCESSIONI.IDUSO, VW_POSTEGGICONCESSIONI.IDPOSTEGGIO, VW_POSTEGGICONCESSIONI.CODICECONCESSIONE, VW_POSTEGGICONCESSIONI.CODICEISTANZA, VW_POSTEGGICONCESSIONI.CODICEOCCUPANTE, VW_POSTEGGICONCESSIONI.CODICETITOLARE, MERCATIPRESENZE_D.* FROM  VW_POSTEGGICONCESSIONI LEFT OUTER JOIN MERCATIPRESENZE_D ON VW_POSTEGGICONCESSIONI.IDCOMUNE = MERCATIPRESENZE_D.IDCOMUNE AND VW_POSTEGGICONCESSIONI.IDPOSTEGGIO = MERCATIPRESENZE_D.FKIDPOSTEGGIO;
Create Or Replace View VW_PROCEDIMENTI_STP as select INVENTARIOPROCEDIMENTI.IDCOMUNE,     NVL(inventarioprocedimentipeople.cod_proc_people, TO_CHAR(inventarioprocedimenti.codiceinventario)) AS codiceSTP,     inventarioprocedimenti.codiceinventario   FROM  INVENTARIOPROCEDIMENTI   LEFT JOIN inventarioprocedimentipeople   ON INVENTARIOPROCEDIMENTI.IDCOMUNE=INVENTARIOPROCEDIMENTIPEOPLE.IDCOMUNE   AND INVENTARIOPROCEDIMENTI.CODICEINVENTARIO=INVENTARIOPROCEDIMENTIPEOPLE.CODICEINVENTARIO;
CREATE OR REPLACE View VW_ALBEROPROC_STP as SELECT VW_procedimenti_STP.IDCOMUNE, alberoproc.SOFTWARE, VW_procedimenti_STP.CODICESTP, VW_procedimenti_STP.CODICEINVENTARIO, alberoproc_endo.fkscid as SC_id FROM  alberoproc,  VW_procedimenti_STP,  alberoproc_endo WHERE alberoproc_endo.idcomune = vw_procedimenti_stp.idcomune and alberoproc_endo.codiceinventario = vw_procedimenti_stp.codiceinventario and alberoproc.idcomune = alberoproc_endo.idcomune and alberoproc.sc_id = alberoproc_endo.fkscid;
CREATE OR REPLACE View VW_PROTOCOLLO_RESPFLUSSI as SELECT IDCOMUNE, case mr_fkidmodalita when 1 then 'A' when 2 then 'P' when 3 then 'I' end as CODICEFLUSSO, mr_fkidresponsabile as CODICERESPONSABILE FROM  prot_modalitaresponsabili;
CREATE OR REPLACE VIEW VW_PROTOCOLLO_TIPIDOCUMENTO
AS
  SELECT IDCOMUNE,
    TO_CHAR(TP_ID) AS CODICE,
    TP_DESCRIZIONE AS DESCRIZIONE
  FROM PROT_TIPOLOGIAPROTOCOLLO
  UNION
  SELECT IDCOMUNE, CODICE, DESCRIZIONE FROM PROTOCOLLO_TIPIDOCUMENTO;
CREATE OR REPLACE View VW_PROVINCE as SELECT SIGLAPROVINCIA, PROVINCIA FROM  COMUNI GROUP BY SIGLAPROVINCIA, PROVINCIA;
CREATE OR REPLACE View VW_REGISTRAZIONIDEBITI as SELECT id_REGISTRAZIONE, IDCOMUNE, SOFTWARE, count(rata_non_pagata) as rate_non_pagate, SUM(importo_rata) as importo_rate, SUM(incassato_rata) as incassato_rate, (SUM(importo_rata) - NVL(SUM(incassato_rata), 0)) as DA_INCASSARE FROM VW_A_REGISTRAZIONI_DEBITI GROUP BY id_registrazione, SOFTWARE, IDCOMUNE;
CREATE OR REPLACE View VW_REGISTRAZIONISALDO as SELECT importi_non_ridotti.id as id, importi_non_ridotti.idcomune as idcomune, importi_non_ridotti.importo_registrazione as importo_registrazione, importi_non_ridotti.incassato + importi_ridotti.incassato as incassato, importi_ridotti.incassato as incassato_ridotto, (saldo_ridotti.saldo - importi_ridotti.incassato) as saldo_ridotto, importi_non_ridotti.incassato as incassato_non_ridotto, importi_non_ridotti.saldo as saldo_non_ridotto, case SIGN(importi_non_ridotti.importo_registrazione) when 1 then  case importi_ridotti.incassato when 0 then  ((importi_non_ridotti.saldo - NVL(saldo_ridotti.saldo, 0)) - (importi_non_ridotti.incassato-(importi_non_ridotti.incassato + importi_ridotti.incassato)))  ELSE  ( importi_non_ridotti.importo_registrazione -(importi_non_ridotti.incassato + NVL(saldo_ridotti.saldo, 0)))  end  ELSE 0 end as saldo 
FROM vw_a_importi_non_ridotti importi_non_ridotti 
LEFT OUTER JOIN vw_a_importi_ridotti importi_ridotti 
ON importi_non_ridotti.idcomune=importi_ridotti.idcomune  
AND importi_non_ridotti.id=importi_ridotti.id 
LEFT OUTER JOIN vw_a_saldo_ridotti saldo_ridotti 
ON importi_non_ridotti.idcomune=saldo_ridotti.idcomune  
AND importi_non_ridotti.id=saldo_ridotti.id;
Create Or Replace View VW_SCADENZARIO as Select BATCH_SCADENZARIO.IDCOMUNE as IDCOMUNE, BATCH_SCADENZARIO.ID as CODICESCADENZA, BATCH_SCADENZARIO.SOFTWARE as software, BATCH_SCADENZARIO.CODICEISTANZA as codiceistanza, ISTANZE.NUMEROPROTOCOLLO as numeroprotocollo, ISTANZE.DATAPROTOCOLLO as dataprotocollo, ISTANZE.NUMEROISTANZA as NUMEROISTANZA, ISTANZE.CHIUSURA as CODSTATOISTANZA, STATIISTANZA.STATO as DESCRSTATOISTANZA, BATCH_SCADENZARIO.CODICEMOVIMENTO as CODMOVIMENTO, BATCH_SCADENZARIO.DESCRMOVIMENTO as DESCRMOVIMENTO, to_char(MOVIMENTI.DATA,'DD/MM/YYYY') as DATAMOVIMENTO, BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE as CODMOVIMENTODAFARE, BATCH_SCADENZARIO.DESCRMOVIMENTODAFARE as DESCRMOVIMENTODAFARE, to_char(BATCH_SCADENZARIO.DATASCADENZA,'DD/MM/YYYY') as DATASCADENZASTR, BATCH_SCADENZARIO.codiceinventario AS codiceinventario, BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE AS CODICEAMMINISTRAZIONE, RESPONSABILI.RESPONSABILE as RESPONSABILE, INVENTARIOPROCEDIMENTI.PROCEDIMENTO as PROCEDIMENTO, TIPIPROCEDURE.PROCEDURA as PROCEDURA, SOFTWARE.DESCRIZIONE as MODULOSOFTWARE, amministrazioni.AMMINISTRAZIONE as AMM_amministrazione, AMMINISTRAZIONI.PARTITAIVA as AMM_PARTITAIVA, AMMINISTRAZIONI.PASSWORD as AMM_PASSWORD, ANAGRAFE.NOMINATIVO || ' ' || ANAGRAFE.NOME as RIC_NOMINATIVO, Nvl(ANAGRAFE.CODICEFISCALE,'') AS RIC_CODICEFISCALE, Nvl(ANAGRAFE.PARTITAIVA,'') AS RIC_PARTITAIVA, ANAGRAFE.INDIRIZZO as RIC_INDIRIZZO, ANAGRAFE.CAP as RIC_CAP, ANAGRAFE.CITTA as RIC_LOCALITA, COMUNERESIDENZA.COMUNE as RIC_CITTA, COMUNERESIDENZA.PROVINCIA as RIC_PROVINCIA, ANAGRAFE.PASSWORD as RIC_PASSWORD, TECNICO.NOMINATIVO || ' ' || TECNICO.NOME as TEC_NOMINATIVO, Nvl(TECNICO.CODICEFISCALE,'') AS TEC_CODICEFISCALE, Nvl(TECNICO.PARTITAIVA,'') AS TEC_PARTITAIVA, TECNICO.PASSWORD as TEC_PASSWORD, AZIENDA.NOMINATIVO || ' ' || AZIENDA.NOME as AZ_NOMINATIVO,Nvl(AZIENDA.CODICEFISCALE,'') AS AZ_CODICEFISCALE, Nvl(AZIENDA.PARTITAIVA,'') AS AZ_PARTITAIVA, AZIENDA.PASSWORD as AZ_PASSWORD, TIPIMOVIMENTO.FK_FO_SOGGETTIESTERNI From BATCH_SCADENZARIO, ISTANZE, RESPONSABILI, INVENTARIOPROCEDIMENTI, MOVIMENTI, TIPIPROCEDURE, SOFTWARE, ANAGRAFE, COMUNI COMUNERESIDENZA, ANAGRAFE TECNICO, ANAGRAFE AZIENDA, STATIISTANZA, AMMINISTRAZIONI, TIPIMOVIMENTO Where ISTANZE.IDCOMUNE=BATCH_SCADENZARIO.IDCOMUNE and ISTANZE.CODICEISTANZA=BATCH_SCADENZARIO.CODICEISTANZA and RESPONSABILI.IDCOMUNE=ISTANZE.IDCOMUNE and RESPONSABILI.CODICERESPONSABILE=ISTANZE.CODICERESPONSABILE and INVENTARIOPROCEDIMENTI.IDCOMUNE=BATCH_SCADENZARIO.IDCOMUNE and INVENTARIOPROCEDIMENTI.CODICEINVENTARIO=BATCH_SCADENZARIO.CODICEINVENTARIO and MOVIMENTI.IDCOMUNE=BATCH_SCADENZARIO.IDCOMUNE and MOVIMENTI.CODICEMOVIMENTO=BATCH_SCADENZARIO.CODICEMOVIMENTO and TIPIMOVIMENTO.IDCOMUNE=BATCH_SCADENZARIO.IDCOMUNE and TIPIMOVIMENTO.TIPOMOVIMENTO=BATCH_SCADENZARIO.TIPOMOVIMENTODAFARE and TIPIPROCEDURE.IDCOMUNE=ISTANZE.IDCOMUNE and TIPIPROCEDURE.CODICEPROCEDURA=ISTANZE.CODICEPROCEDURA and SOFTWARE.CODICE=BATCH_SCADENZARIO.SOFTWARE and ANAGRAFE.IDCOMUNE = ISTANZE.IDCOMUNE and ANAGRAFE.CODICEANAGRAFE = ISTANZE.CODICERICHIEDENTE AND COMUNERESIDENZA.CODICECOMUNE(+) = ANAGRAFE.COMUNERESIDENZA and TECNICO.IDCOMUNE(+) = ISTANZE.IDCOMUNE and TECNICO.CODICEANAGRAFE(+) = ISTANZE.CODICEPROFESSIONISTA AND AZIENDA.IDCOMUNE(+) = ISTANZE.IDCOMUNE and AZIENDA.CODICEANAGRAFE(+) = ISTANZE.CODICETITOLARELEGALE AND STATIISTANZA.IDCOMUNE = ISTANZE.IDCOMUNE and STATIISTANZA.SOFTWARE = ISTANZE.SOFTWARE and STATIISTANZA.CODICESTATO = ISTANZE.CHIUSURA and AMMINISTRAZIONI.IDCOMUNE = BATCH_SCADENZARIO.IDCOMUNE and AMMINISTRAZIONI.CODICEAMMINISTRAZIONE = BATCH_SCADENZARIO.CODICEAMMINISTRAZIONE WITH READ ONLY;
CREATE OR REPLACE View VW_STATISTICHEISTANZE as SELECT DISTINCT ISTANZE.IDCOMUNE as f_idcomune, ISTANZE.SOFTWARE as f_software, ISTANZE.DATA as f_data, NVL(ISTANZE.codiceResponsabile, -1) as f_responsabile, NVL(ISTANZE.codiceprofessionista, -1) as f_professionista, NVL(ISTANZE.CODICEINTERVENTOPROC, ISTANZE.CODICEINTERVENTO) as f_codiceintervento, NVL(ISTANZE.METRIQUADRATI, 0) as f_metriquadrati, NVL(ISTANZE.CODICEPROCEDURA, -1) as f_procedura, NVL(ISTANZEATTIVITA.CodiceAttivita, ' ') as f_dettaglioinformazioni, NVL(SETTORI.CodiceSettore, -1) as f_tipoinformazioni, NVL(ISTANZEAREE.CODICEAREA, -1) as f_zonizzazione, NVL(AUTORIZZAZIONI.FKIDREGISTRO, -1) as f_registro, NVL(ISTANZE.CHIUSURA, ' ') as f_stato, ISTANZE.CODICEISTANZA, ISTANZE.CODICERESPONSABILE, ISTANZE.CODICERICHIEDENTE, ISTANZE.CODICEPROFESSIONISTA, ISTANZE.DATA, ISTANZE.NUMEROPROTOCOLLO, ISTANZE.DATAPROTOCOLLO, ISTANZE.CODICEINTERVENTO, ISTANZE.LAVORI, ISTANZE.CODICEPROCEDURA, ISTANZE.CODICEAREA, ISTANZE.CODICELOTTO, ISTANZE.PASSWORD, ISTANZE.ATTIVA, ISTANZE.FOGLIO, ISTANZE.PARTICELLA, ISTANZE.SUB, ISTANZE.CODICESETTORE, ISTANZE.VARIANTEPR, ISTANZE.CODICEIMPIANTO, ISTANZE.CODICEATTIVITA, ISTANZE.FLAGVIA, ISTANZE.CHIUSURA, ISTANZE.PROGREGAUT, ISTANZE.LAVORIESTESA, ISTANZE.CODICEARCHIVIO, ISTANZE.CODICESTRADARIO, ISTANZE.CIVICO, ISTANZE.AUTORIZNUMERO, ISTANZE.AUTORIZDATA, ISTANZE.AUTORIZDATAREGISTR, ISTANZE.AUTORIZRESPONSABILE, ISTANZE.TIPOMOVAVVIO, ISTANZE.TIPOARCHIVIO, ISTANZE.CODICECOMUNE, ISTANZE.SOFTWARE, ISTANZE.IDMODELLO, ISTANZE.CODICEINTERVENTOPROC, ISTANZE.NUMEROISTANZA, ISTANZE.IDCOMUNE, ISTANZE.SETITOLARELEGALE, ISTANZE.FKIDTIPOLOGIAISTANZA, ISTANZE.CODICETITOLARELEGALE, ISTANZE.FKTOID, ISTANZE.METRIQUADRATI, ISTANZE.GIORNOCHIUSURA, ISTANZE.CODISTANZACOLLEGATA, ISTANZE.AZIONE, ISTANZE.FKIDREGISTRO, ISTANZE.NOMEATTIVITA, ISTANZE.FKIDFORMATO, ISTANZE.POSIZIONEARCHIVIO, ISTANZE.BASE, ISTANZE.ALTEZZA, ISTANZE.FACCE, ISTANZE.FKIDPROTOCOLLO, ISTANZE.FKCODICESOGGETTO, ISTANZE.CODICEISTRUTTORE, ISTANZE.CODICERESPONSABILEPROC, ISTANZE.CODICEAREA2, ISTANZE.FK_IDI_ATTIVITA, ISTANZE.DATAVALIDITA, ISTANZE.I_ATTIVITAORDINE, ISTANZE.CREATO_DA_STC, ISTANZE.DESCRSOGGETTO FROM ISTANZE LEFT OUTER JOIN ISTANZEATTIVITA LEFT OUTER JOIN ATTIVITA LEFT OUTER JOIN SETTORI ON ATTIVITA.IDCOMUNE=SETTORI.IDCOMUNE  AND ATTIVITA.CODICESETTORE=SETTORI.CODICESETTORE ON ISTANZEATTIVITA.IDCOMUNE=ATTIVITA.IDCOMUNE  AND ISTANZEATTIVITA.CODICEATTIVITA=ATTIVITA.CODICEISTAT ON ISTANZE.IDCOMUNE=ISTANZEATTIVITA.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEATTIVITA.CODICEISTANZA  LEFT OUTER JOIN ISTANZEAREE ON ISTANZE.IDCOMUNE=ISTANZEAREE.IDCOMUNE  AND ISTANZE.CODICEISTANZA=ISTANZEAREE.CODICEISTANZA  LEFT OUTER JOIN AUTORIZZAZIONI ON ISTANZE.IDCOMUNE=AUTORIZZAZIONI.IDCOMUNE  AND ISTANZE.CODICEISTANZA=AUTORIZZAZIONI.FKIDISTANZA;
CREATE OR REPLACE VIEW VW_STRADARIO
AS
  SELECT CODICESTRADARIO,
    TRIM(PREFISSO
    || ' '
    || DESCRIZIONE) AS INDIRIZZO,
    PREFISSO,
    DESCRIZIONE,
    CAP,
    LOCFRAZ,
    FKIDZONA,
    CODICECOMUNE,
    IDCOMUNE,
    CS_DATE,
    CODVIARIO,
    DATAVALIDITA
  FROM STRADARIO
WITH READ ONLY;
CREATE OR REPLACE View VW_TMPSTAT_MAX_COLLEGAMENTO as SELECT SESSIONID, IDPRATICA, CODICEISTANZA, MAX(ORDINECOLLEGAMENTO) as ORDINECOLLEGAMENTO FROM  TMP_STAT_02 GROUP BY SESSIONID, IDPRATICA, CODICEISTANZA;